/* Fuse.js lite (local, no external dependency) */
(function (global) {
  function normalize(text) {
    return String(text || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '');
  }

  function getValue(item, key) {
    if (!key) return '';
    if (typeof key === 'function') return key(item);
    const path = String(key).split('.');
    let value = item;
    for (let i = 0; i < path.length; i += 1) {
      if (value == null) return '';
      value = value[path[i]];
    }
    return value == null ? '' : value;
  }

  function scorePattern(pattern, text) {
    if (!pattern) return 0;
    if (!text) return 1;
    if (text.indexOf(pattern) !== -1) {
      const ratio = pattern.length / Math.max(1, text.length);
      return 0.08 + ratio * 0.12;
    }
    let pi = 0;
    let ti = 0;
    let matches = 0;
    while (pi < pattern.length && ti < text.length) {
      if (pattern[pi] === text[ti]) {
        matches += 1;
        pi += 1;
      }
      ti += 1;
    }
    if (!matches) return 1;
    const coverage = matches / pattern.length;
    const spread = matches / text.length;
    return 1 - (coverage * 0.7 + spread * 0.3);
  }

  function Fuse(list, options) {
    this.list = Array.isArray(list) ? list : [];
    this.options = options || {};
    const keys = this.options.keys || [];
    this.keys = keys.map(function (key) {
      return typeof key === 'object' && key ? key.name : key;
    });
    this.threshold = typeof this.options.threshold === 'number' ? this.options.threshold : 0.6;
  }

  Fuse.prototype.search = function (pattern) {
    const query = normalize(pattern);
    const results = [];
    for (let i = 0; i < this.list.length; i += 1) {
      const item = this.list[i];
      let best = 1;
      if (!this.keys.length) {
        best = scorePattern(query, normalize(item));
      } else {
        for (let k = 0; k < this.keys.length; k += 1) {
          const value = normalize(getValue(item, this.keys[k]));
          const score = scorePattern(query, value);
          if (score < best) best = score;
          if (best === 0) break;
        }
      }
      if (best <= this.threshold) {
        results.push({ item: item, refIndex: i, score: best });
      }
    }
    results.sort(function (a, b) {
      return a.score - b.score;
    });
    return results;
  };

  Fuse.version = '6.0.0-lite';
  global.Fuse = Fuse;
})(this);
